import torch
import torch.nn as nn
DT = torch.float16
ROWS, HIDDEN = 8192, 2048

class Model(nn.Module):
    def __init__(self, dt=DT, hidden=HIDDEN):
        super().__init__()
        dev = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        g = torch.Generator().manual_seed(0)
        self.w=nn.Parameter((0.02*torch.randn(HIDDEN,HIDDEN,generator=g)).to(dev,dt))
        self.b=nn.Parameter((0.1*torch.randn(HIDDEN,generator=g)).to(dev,dt))
    def forward(self, x):
        return torch.relu(x@self.w+self.b*1.0)

def get_inputs():
    g = torch.Generator().manual_seed(1)
    return [(torch.randn(ROWS, HIDDEN, generator=g)).to(torch.device("cuda" if torch.cuda.is_available() else "cpu"), DT)]

